// Exact private derived-index requests. Comparisons never select authority.
#[derive(serde::Deserialize)]#[serde(deny_unknown_fields)]
struct HistoricalSearchBaseline{statuses:[u16;4],sha256:[String;4]}
#[derive(serde::Deserialize)]#[serde(deny_unknown_fields)]
struct HistoricalSearchPlan{terms:[String;3],baselines:[HistoricalSearchBaseline;3]}
fn historical_search_nonnull_optional<'de,D:serde::Deserializer<'de>>(d:D)->Result<Option<HistoricalSearchPlan>,D::Error>{HistoricalSearchPlan::deserialize(d).map(Some)}
fn historical_search_term(s:&str)->bool{!s.is_empty()&&s.len()<=64&&s.bytes().all(|b|b.is_ascii_lowercase())}
impl HistoricalSearchPlan{fn valid(&self)->bool{self.terms.iter().all(|s|historical_search_term(s))&&self.terms[0]!=self.terms[1]&&self.terms[0]!=self.terms[2]&&self.terms[1]!=self.terms[2]&&self.baselines.iter().all(|b|b.statuses[0]==200&&b.statuses[1]==200&&matches!(b.statuses[2],403|404)&&b.statuses[3]==401&&b.sha256.iter().all(|v|historical_sha(v)))}}
fn historical_search_path(space:&str,term:&str)->String{format!("/api/v1/search?q={term}&space_id={space}&is_draft=false&limit=8")}
fn historical_search_routes_valid(routes:&[HistoricalReadonlyRoute])->bool{
 let rebuilds=routes.iter().filter_map(|r|if let HistoricalReadonlyRoute::SearchReindex{published_source_digest,..}=r{Some(published_source_digest)}else{None}).collect::<Vec<_>>();let searches=routes.iter().filter_map(|r|if let HistoricalReadonlyRoute::SearchPublished{space,term,page,published_source_digest}=r{Some((space,term,page,published_source_digest))}else{None}).collect::<Vec<_>>();if rebuilds.len()!=1||searches.len()!=3{return false;}
 let pages=routes.iter().filter_map(|r|if let HistoricalReadonlyRoute::PageMetadata{space,page,..}=r{Some((space,page))}else{None}).collect::<std::collections::BTreeSet<_>>();let selected=searches.iter().filter_map(|(space,_,page,_)|page.as_ref().map(|page|(*space,page))).collect::<std::collections::BTreeSet<_>>();pages.len()==2&&selected==pages&&searches.iter().filter(|(_,_,page,_)|page.is_none()).count()==1&&searches.iter().all(|(space,_,_,sha)|*sha==rebuilds[0]&&*space==searches[0].0)&&searches.iter().map(|(_,term,_,_)|*term).collect::<std::collections::BTreeSet<_>>().len()==3
}
async fn historical_source_search_routes(source:&mut StoppedHistoricalVerificationSource<'_>,selected:&HistoricalDataSelection,plan:&HistoricalSearchPlan)->anyhow::Result<Vec<HistoricalReadonlyRoute>>{
 source.fence().await?;anyhow::ensure!(plan.valid(),"Exact original search plan invalid");
 let docs:Vec<(String,String,String,String)>=sqlx::query_as("SELECT id,space_id,title,content_path FROM documents WHERE published_at IS NOT NULL AND archived_at IS NULL AND deleted_at IS NULL ORDER BY id").fetch_all(&mut *source.original.conn).await?;
 anyhow::ensure!(!docs.is_empty()&&docs.len()<=8,"Original published search source exceeds finite8");let mut facts=Vec::new();let mut matches:[Vec<String>;3]=Default::default();
 for(id,space,title,path)in &docs{
  let row=crate::spaces::published_source::selected(source.original.conn,space,id).await.map_err(|_|fail("Original published search row unavailable"))?;
  let(file,stamp,sha)=source.original.inventory.files.get(path).ok_or_else(||fail("Original published search body not held"))?;anyhow::ensure!(stamp.length<=6_000_000&&physical_stamp(file)?==*stamp&&hash_file(file,stamp.length)?==*sha,"Original published search native body changed");let mut bytes=vec![0;stamp.length as usize];file.read_exact_at(&mut bytes,0)?;let body=String::from_utf8(bytes)?;
  let tags=crate::spaces::document_deletion::rows(source.original.conn,"SELECT t.id,t.name FROM tags t JOIN doc_tags dt ON t.id=dt.tag_id WHERE dt.document_id=$1 AND t.space_id=$2 ORDER BY t.id",&[id,space]).await.map_err(|_|fail("Original scoped search tags unavailable"))?;
  let indexed=format!("{title}\n{body}\n{}",tags.iter().filter_map(|t|t["name"].as_str()).collect::<Vec<_>>().join(" "));
  for(i,term)in plan.terms.iter().enumerate(){if indexed.contains(term){matches[i].push(id.clone());}}
  facts.push(serde_json::json!({"row":row,"length":stamp.length,"sha256":sha,"tags":tags}));
 }
 anyhow::ensure!(matches[0]==[selected.page.clone()]&&matches[1]==[selected.related_page.clone()]&&matches[2].is_empty(),"Original exact published/draft search terms not unique source facts");
 let draft=crate::spaces::draft_save::selected(source.original.conn,&selected.space,&selected.page,&selected.draft).await.map_err(|_|fail("Original search exclusion draft unavailable"))?;anyhow::ensure!(draft["content"].as_str().is_some_and(|v|v.contains(&plan.terms[2])),"Original private search term absent from actual draft");let draft_sha=crate::spaces::draft_save::digest(&draft).map_err(|_|fail("Original search exclusion draft digest unavailable"))?;
 let published_source_digest=digest(&serde_json::to_vec(&(facts,draft_sha))?);let mut routes=vec![HistoricalReadonlyRoute::SearchReindex{published_source_digest:published_source_digest.clone(),count:docs.len()}];
 for(i,term)in plan.terms.iter().enumerate(){routes.push(HistoricalReadonlyRoute::SearchPublished{space:selected.space.clone(),term:term.clone(),page:match i{0=>Some(selected.page.clone()),1=>Some(selected.related_page.clone()),_=>None},published_source_digest:published_source_digest.clone()});}
 source.fence().await?;Ok(routes)
}
async fn historical_actual_search_matrix(source:&mut StoppedHistoricalVerificationSource<'_>,handoff:&HistoricalReadonlyChildHandoff,client:&reqwest::Client,base:&str,plan:&HistoricalSearchPlan,credentials:&HistoricalDataCredentials,secret:&str)->anyhow::Result<()>{
 let reindex=handoff.wire.routes.iter().find(|r|matches!(r,HistoricalReadonlyRoute::SearchReindex{..})).ok_or_else(||fail("Exact historical reindex route absent"))?;let HistoricalReadonlyRoute::SearchReindex{count,..}=reindex else{unreachable!()};
 // Denied real audiences run first. Only actual current admin may rebuild.
 for index in [1usize,2,3,0]{historical_data_audiences_fence(source,credentials,secret).await?;handoff.fence()?;let clock=std::time::Instant::now();let mut request=client.post(format!("{base}{}",historical_route_path(reindex)));let token=match index{0=>Some(&credentials.producer),1=>Some(&credentials.allowed),2=>Some(&credentials.outsider),_=>None};if let Some(token)=token{request=request.bearer_auth(token);}let response=request.send().await?;let status=response.status().as_u16();let value:serde_json::Value=response.json().await.map_err(|_|fail("Historical real reindex response unavailable"))?;historical_data_audiences_fence(source,credentials,secret).await?;handoff.fence()?;anyhow::ensure!(if index==0{status==200&&value==serde_json::json!({"status":"reindex_complete","documents_indexed":count})}else{status==401},"Actual real historical reindex current-admin policy refused");eprintln!("HISTORICAL_SEARCH_PARENT_PHASE role=reindex audience={index} status={status} elapsed_ms={}",clock.elapsed().as_millis());}
 let routes=handoff.wire.routes.iter().filter(|r|matches!(r,HistoricalReadonlyRoute::SearchPublished{..})).collect::<Vec<_>>();anyhow::ensure!(routes.len()==3,"Exact historical search route set incomplete");
 for(i,route)in routes.into_iter().enumerate(){let HistoricalReadonlyRoute::SearchPublished{term,page,..}=route else{unreachable!()};anyhow::ensure!(term==&plan.terms[i],"Exact historical search comparison order differs");let path=historical_route_path(route);
  for(index,token)in [Some(credentials.producer.as_str()),Some(credentials.allowed.as_str()),Some(credentials.outsider.as_str()),None].into_iter().enumerate(){let clock=std::time::Instant::now();historical_data_audiences_fence(source,credentials,secret).await?;handoff.fence()?;let mut request=client.get(format!("{base}{path}"));if let Some(token)=token{request=request.bearer_auth(token);}let response=request.send().await?;let status=response.status().as_u16();let value:serde_json::Value=response.json().await.map_err(|_|fail("Historical selected search JSON unavailable"))?;historical_data_audiences_fence(source,credentials,secret).await?;handoff.fence()?;
   anyhow::ensure!(status==plan.baselines[i].statuses[index]&&digest(&serde_json::to_vec(&value)?)==plan.baselines[i].sha256[index],"Actual exact per-human historical search presentation differs");
   if index<2{let values=value.as_array().ok_or_else(||fail("Actual historical published search array absent"))?;match page{Some(page)=>anyhow::ensure!(values.len()==1&&values[0]["document_id"]==*page&&values[0]["is_draft"]==false&&values[0]["draft_id"].is_null(),"Actual historical exact current private published search differs"),None=>anyhow::ensure!(values.is_empty(),"Unpublished private draft leaked into historical published search")}}
   eprintln!("HISTORICAL_SEARCH_PARENT_PHASE role=published query={i} audience={index} status={status} elapsed_ms={}",clock.elapsed().as_millis());
  }
 }
 // Entire raw URI must match: alternate query grammar/method/body never reaches handlers.
 let exact=historical_route_path(handoff.wire.routes.iter().find(|r|matches!(r,HistoricalReadonlyRoute::SearchPublished{..})).ok_or_else(||fail("Exact historical search route absent"))?);
 for(method,path,body)in [(reqwest::Method::GET,format!("{exact}&extra=1"),""),(reqwest::Method::GET,format!("{exact}&q=duplicate"),""),(reqwest::Method::POST,exact.clone(),""),(reqwest::Method::GET,"/api/v1/admin/search/reindex".into(),""),(reqwest::Method::POST,"/api/v1/admin/search/reindex?extra=1".into(),""),(reqwest::Method::POST,"/api/v1/admin/search/reindex".into(),"x")]{let response=client.request(method,format!("{base}{path}")).bearer_auth(&credentials.producer).body(body).send().await?;anyhow::ensure!(response.status()==reqwest::StatusCode::SERVICE_UNAVAILABLE,"Unselected historical search method/query/body reached handler");}
 historical_data_audiences_fence(source,credentials,secret).await?;handoff.fence()?;println!("ACTUAL_NORMAL_HISTORICAL_REAL_REINDEX_PRIVATE_PUBLISHED_SEARCH_DRAFT_EXCLUSION_ALL_AUDIENCES_PASS");Ok(())
}
